window.DICTIONARY_ENTRY_SHARDS["0079-006f"]={"0079-006f:eb63f0d7e6867f":{"word":"Yorkshireterrier","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"York·shire·ter·ri·er","de-DE":"York·shire·ter·ri·er"},"forms":[{"form":"Yorkshireterrier","tags":["Nominativ","Singular"]},{"form":"Yorkshire-Terrier","tags":["alternative"]},{"form":"Yorkshireterriern","tags":["Dativ","Plural"]},{"form":"Yorkshireterriers","tags":["Genitiv","Singular"]}],"senses":[{"definition":"eine Hunderasse, die zur Gruppe der Terrier gehört"}],"synonyms":[],"origins":["Determinativkompositum, zusammengesetzt aus Yorkshire (einer Grafschaft in England, in der das Tier ursprünglich gezüchtet wurde), und Terrier"],"examples":[{"text":"Da es ihm nicht an Selbstsicherheit fehlt, gefällt sich der Yorkshireterrier im Ausstellungsring, wo er durchaus die Aufmerksamkeit auf sich zu lenken versucht. (de.wikipedia.org)","reference":""},{"text":"„Depp soll seine Yorkshireterrier Pistol und Boo an Bord eines Privatjets heimlich nach Australien gebracht haben, obwohl die Quarantäne-Auflagen des Landes äußerst strikt sind.“","reference":"Johnny Depp droht in Australien Anklage wegen Meineids. Abgerufen am 3. Juni 2019."}],"idioms":[],"collocations":[],"derivations":["Yorkshireterrierbesitzer","Yorkshireterrierbesitzerin"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Yorkshireterrier","id":"eb63f0d7e6867f"},"0079-006f:8620cee828732d":{"word":"Yoga","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Yoga","de-DE":"Yoga"},"forms":[{"form":"Joga","tags":["obsolete"]},{"form":"Yoga","tags":["Nominativ","Singular"]},{"form":"Yogas","tags":["Genitiv","Singular"]}],"senses":[{"definition":"ein aus dem so genannten östlichen, dem indischen Kulturkreis stammendes philosophisches System mit geistigen und körperlichen Übungen zur Erlangung verschiedener mentaler und körperlichen Fähigkeiten"},{"definition":"eine an das so genannte westliche Denken angepasste gymnastische und meditative Sportart"}],"synonyms":["Joga"],"origins":["Entlehnung aus dem sanskritischen योगः (yōgaḥ) ^(→ sa) (Stamm: योग (yōga) ^(→ sa)) mit der Grundbedeutung „Verbindung, Vereinigung“ Der Name Yoga leitet sich von Sanskrit „Yuj“ ab und bedeutet das Anbinden oder Anschirren von Zugtieren vor einen Wagen. Die menschlichen Sinne werden vor den menschlichen Körper, das Fahrzeug der menschlichen Seele gespannt, um zur Selbstverwirklichung zu gelangen. Das Wort Yoga wird in der Bhagavad-Gita jedoch in verschiedenen Bedeutungen gebraucht."],"examples":[{"text":"Mit Techniken des Yoga lassen sich Konzentration, Selbstdisziplin und positives Denken erreichen.","reference":""},{"text":"Meine Mutter geht jeden Mittwoch zum Yoga.","reference":""},{"text":"„Heute ist dieser selbsternannte Anhänger der Janosch-eigenen Art des Buddhismus, abgehärtet durch Yoga und von der spanischen Sonne gewärmt, ein glücklicher Mensch.“","reference":"Angela Bajorek: Wer fast nichts braucht, hat alles. Janosch. Die Biographie. Ullstein, Berlin 2016, ISBN 978-3-550-08125-5 , Seite 10. Polnisches Original 2015."},{"text":"„Yoga ist etwas Spezielles.","reference":"Kaya Yanar: Made in Germany. 3. Auflage. Wilhelm Heyne, München 2011, ISBN 978-3-453-60204-5, Seite 64."}],"idioms":[],"collocations":[],"derivations":["Yogahose","Yogaklasse","Yogakurs","Yogalehrer","Yogamatte","Yogaregel","Yogaschule","Yogastudio","Yogastunde","Yogatechniken","Yogaübung","Yogi"],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Yoga","id":"8620cee828732d"},"0079-006f:be1fb66ca7984b":{"word":"Yo-Yo","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Yo-Yo","de-DE":"Yo-Yo"},"forms":[{"form":"Yo-Yo","tags":["Nominativ","Singular"]},{"form":"Yo-Yos","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Spielzeug aus zwei Scheiben"}],"synonyms":["Jo-Jo"],"origins":[],"examples":[{"text":"„Wusstest du, dass man im Weltall nicht mit Yo-Yos spielen kann?“","reference":"Fehlender Parameter (Hilfe) Abgerufen am 13. November 2019."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Yo-Yo","id":"be1fb66ca7984b"},"0079-006f:1b7bb66acfddee":{"word":"Yotta-","partOfSpeech":"Gebundenes Lexem","gender":"","hyphenation":{"de-CH":"Yot·ta-","de-DE":"Yot·ta-"},"forms":[],"senses":[{"definition":"Vorsatz für SI-Einheiten, SI-Einheiten-Präfix für Maßeinheiten bedeutet 1.000.000.000.000.000.000.000.000 (Quadrillion)"}],"synonyms":[],"origins":["von italienisch otto ^(→ it) „Acht“"],"examples":[{"text":"Die Strahlungsleistung der Sonne beträgt etwa 380 Yottawatt.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Yotta-","id":"1b7bb66acfddee"},"0079-006f:8f60dfbaaf7d44":{"word":"Yokto-","partOfSpeech":"Gebundenes Lexem","gender":"","hyphenation":{"de-CH":"Yok·to-","de-DE":"Yok·to-"},"forms":[{"form":"y","tags":["Kurzform"]}],"senses":[{"definition":"Vorsatz für SI-Einheiten, SI-Einheiten-Präfix für Maßeinheiten bedeutet ein Quadrillionstel = (10⁻³)⁸ = 10⁻²⁴"}],"synonyms":[],"origins":["lateinisch octo ^(→ la) = acht"],"examples":[{"text":"Yoktometer","reference":""}],"idioms":[],"collocations":[],"derivations":["Yoktometer"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Yokto-","id":"8f60dfbaaf7d44"},"0079-006f:af3ec1d2d709cc":{"word":"Yogaübung","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Yo·ga·übung","de-DE":"Yo·ga·übung"},"forms":[{"form":"Jogaübung","tags":["obsolete"]},{"form":"Yogaübung","tags":["Nominativ","Singular"]},{"form":"Yogaübungen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"eine bestimmte Körperhaltung oder Körperbewegung (Übung), die zum Yoga gehört"}],"synonyms":[],"origins":["Determinativkompositum (Zusammensetzung) der Substantive Yoga und Übung"],"examples":[{"text":"„Möglicherweise wenden auch menschliche Rekordtaucher, die mit Yogaübungen das Luftanhalten trainieren, das Prinzip des gedrosselten Stoffwechsels an, spekulieren die Forscher […].“","reference":"König der Taucher. In: Zeit Online. Nummer 28/1997, 4. Juli 1997, ISSN 0044-2070 (URL, abgerufen am 8. Dezember 2012) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Yogaübung","id":"af3ec1d2d709cc"},"0079-006f:9ee99384e8a731":{"word":"Yottabyte","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Yot·ta·byte","de-DE":"Yot·ta·byte"},"forms":[{"form":"YB","tags":["Kurzform"]},{"form":"Yottabyte","tags":["Nominativ","Singular"]},{"form":"Yottabytes","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Informatik, eine Mengeneinheit, siehe auch Byte"}],"synonyms":[],"origins":["Determinativkompositum aus dem gebundenen Lexem Yotta- und dem Substantiv Byte, siehe auch Byte"],"examples":[{"text":"Dieses Cluster hat ein Speichervolumen von 80 Yottabytes.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Yottabyte","id":"9ee99384e8a731"},"0079-006f:52a8773311f0a3":{"word":"Yobibyte","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Yo·bi·by·te","de-DE":"Yo·bi·by·te"},"forms":[{"form":"YiB","tags":["Kurzform"]},{"form":"Yobibyte","tags":["Nominativ","Singular"]},{"form":"Yobibytes","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Maßeinheit der Datenmenge, 1 Yobibyte = 1024 Zebibyte = 2⁸⁰ Byte ≈ 1,209·10²⁴ Byte"}],"synonyms":[],"origins":["Wegen der besonderen Bedeutung von 2er-Potenzen in der Informatik wurde ein Yottabyte oft als 2⁸⁰ Byte interpretiert. Das Präfix Yotta- hat jedoch die im internationalen Einheitensystem festgelegte Bedeutung 10²⁴. Daher wurden von der internationalen elektrotechnischen Kommission neue Präfixe auf Grundlage des Binärsystems festgelegt. Das Präfix für 2⁸⁰ lautet dabei Yobi, abgeleitet von Yotta- und der ersten Silbe von binär."],"examples":[{"text":"Ein Yobibyte umfasst 21 % mehr Bits als ein Yottabyte.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Yobibyte","id":"52a8773311f0a3"},"0079-006f:36c6a2ed717d9a":{"word":"Yorck","partOfSpeech":"Vorname","gender":"der","hyphenation":{"de-CH":"Yorck","de-DE":"Yorck"},"forms":[{"form":"Y.","tags":["Kurzform"]},{"form":"Jork","tags":["alternative"]},{"form":"York","tags":["alternative"]},{"form":"Yorck","tags":["Nominativ","Singular"]},{"form":"Yorcke","tags":["Nominativ","Plural"]},{"form":"Yorcks","tags":["Nominativ","Plural"]},{"form":"Yorcken","tags":["Dativ","Plural"]}],"senses":[{"definition":"männlicher Vorname"}],"synonyms":[],"origins":["Yorck ist eine alternative Schreibweise von Jork."],"examples":[{"text":"Das Sonnenblumenbild, an dem Yorck vier Monate lang gestickt hat, ist nun endlich fertig.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Yorck","id":"36c6a2ed717d9a"},"0079-006f:e008dee6c04ace":{"word":"Yoruba","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Yo·ru·ba","de-DE":"Yo·ru·ba"},"forms":[{"form":"Yoruba","tags":["Nominativ","Singular"]},{"form":"yo","tags":["Kurzform"]},{"form":"yor","tags":["Kurzform"]},{"form":"Yorubas","tags":["Genitiv","Singular"]},{"form":"des Yoruba","tags":["Genitiv","Singular"]},{"form":"des Yorubas","tags":["Genitiv","Singular"]},{"form":"(das) Yoruba","tags":["Nominativ","Singular"]},{"form":"(dem) Yoruba","tags":["Dativ","Singular"]}],"senses":[{"definition":"hauptsächlich im Südwesten Nigerias lebendes Volk"},{"definition":"ein Angehöriger des gleichnamigen Volkes"},{"definition":"in Nigeria, Benin und Togo gesprochenes Dialektkontinuum"},{"definition":"die Standardvarietät der Dialekte, die als eine der Nationalsprache Benins und Nigerias gilt"}],"synonyms":[],"origins":[],"examples":[{"text":"„Bei vielen Völkern sind auch Geschichten lebendig, die man Ursprungsmythen nennt; die Fulbe in weiten Teilen Westafrikas, die Yoruba und Edo im heutigen Nigeria, die nach ihrer Sprache Bantu-Völker genannten Gruppen und viele andere afrikanische Völker kennen solche Überlieferungen, in denen von Wanderungen aus einer fernen Heimat in einer mythischen Vergangenheit die Rede ist.“","reference":"Leonhard Harding: Das Königreich Benin. Geschichte – Kultur – Wirtschaft. Oldenbourg, München 2010, ISBN 978-3-486-59757-8, Seite 184 ."},{"text":"„Bei den Yoruba ist es Brauch, Zwillinge Taiwo und Kehinde zu nennen.“","reference":"Oyinkan Braithwaite: Meine Schwester, die Serienmörderin. Blumenbar, Berlin 2020, ISBN 978-3-351-05074-0, Seite 194 ."},{"text":"„Er ist Yoruba, kommt aus Ilorin.“","reference":"Elnathan John: An einem Dienstag geboren. Das Wunderhorn, Heidelberg 2017, ISBN 978-3-884-23552-2, Seite 41 ."},{"text":"„Die rund 15 Yoruboid-Sprachen sind mit dem Yoruba relativ eng verwandt; sie werden von etwa 22 Millionen Menschen in Südwest-Nigeria, Benin und Togo gesprochen.“","reference":"Wikipedia-Artikel „Yoruboid-Sprachen“"},{"text":"„Nasallaute werden im Yoruba nach französischem Muster durch Anhängen eines n an den Vokal dargestellt, dessen ursprünglicher Lautwert jedoch erhalten bleibt.“","reference":"„Zum Verstehen afrikanischer Musik“, Seite 261, Gerhard Kubik, LIT Verlag Münster, 2004 ISBN 3825878007"},{"text":"„Yoruba erlaubt bei einem dreistelligen Verb wie geben lediglich die strukturelle Realisierung des mittleren Arguments (=Rezipient).“","reference":"„Komposition und Argumentstruktur komplexer Verben: eine lexikalische Analyse von Verb-Verb-Komposita und Serialverbkonstruktionen“, Seite 223, Thomas Gamerschlag, Akademie Verlag, 2005 ISBN 3050041439"},{"text":"„In Yoruba beginnen viele Vornamen in Bezug auf Elfen mit Win.“","reference":"„Welt und Wirkungsprinzip“, Werner Landgraf, 2010 ISBN 1445741296"},{"text":"„Im schnellsten Yoruba bellte er etwas ins Telefon und beendete nach einer Minute das Gespräch.“","reference":"Chika Unigwe: Schwarze Schwestern. Roman. Tropen, Stuttgart 2010, ISBN 978-3-608-50109-4, Seite 37. Originalausgabe: Niederländisch 2007."},{"text":"„Malam Abdul-Nur sagte was auf Yoruba zu ihm und ging.“","reference":"Elnathan John: An einem Dienstag geboren. Das Wunderhorn, Heidelberg 2017, ISBN 978-3-884-23552-2, Seite 93 ."}],"idioms":[],"collocations":[],"derivations":["Yorubaland","Yoruboid-Sprachen","Yoruboid"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Yoruba","id":"e008dee6c04ace"},"0079-006f:0bee2988744259":{"word":"Yottagramm","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Yot·ta·gramm","de-DE":"Yot·ta·gramm"},"forms":[{"form":"Yg","tags":["Kurzform"]},{"form":"Yottagramm","tags":["Nominativ","Singular"]},{"form":"Yottagramme","tags":["Nominativ","Plural"]},{"form":"Yottagramms","tags":["Genitiv","Singular"]},{"form":"Yottagrammen","tags":["Dativ","Plural"]}],"senses":[{"definition":"10²⁴ Gramm"}],"synonyms":[],"origins":[],"examples":[{"text":"Die Masse der Erde beträgt 6000 Yottagramm.","reference":"Andrew S. Tanenbaum: Moderne Betriebssysteme. 3. Auflage. Pearson Studium, 2009, ISBN 978-3-8273-7342-7"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Yottagramm","id":"0bee2988744259"},"0079-006f:36d9f00bf4c950":{"word":"Yottajoule","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Yot·ta·joule","de-DE":"Yot·ta·joule"},"forms":[{"form":"YJ","tags":["Kurzform"]},{"form":"Yottajoule","tags":["Nominativ","Singular"]}],"senses":[{"definition":"10²⁴ Joule"}],"synonyms":[],"origins":[],"examples":[{"text":"Die Sonne liefert pro Jahr eine Energiemenge von etwa 3,9 Yottajoule auf die Erdoberfläche, das sind 3,9 Millionen Exajoule, wobei ein Exajoule wiederum einer Milliarde Gigajoule entspricht, […]","reference":"Peter Mersch: Evolution, Zivilisation und Verschwendung. Über den Ursprung von allem. 4. Auflage. Books on Demand GmbH, Norderstedt 2008, ISBN 3837057925"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Yottajoule","id":"36d9f00bf4c950"},"0079-006f:88f5516be9d488":{"word":"Yogi","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Yogi","de-DE":"Yogi"},"forms":[{"form":"Jogi","tags":["alternative"]},{"form":"Yogi","tags":["Nominativ","Singular"]},{"form":"Jogin","tags":["variant"]},{"form":"Yogin","tags":["variant"]},{"form":"Yogis","tags":["Nominativ","Plural"]},{"form":"Yogini","tags":["feminine"]}],"senses":[{"definition":"indischer Asket, der Yoga praktiziert"},{"definition":"Anhänger des Yoga"}],"synonyms":[],"origins":["Entlehnung aus dem sanskritischen योगी (yogī) ^(→ sa) (Stamm: योगिन् (yogin) ^(→ sa))"],"examples":[{"text":"Der Yogi soll beständig sich mühen in der Einsamkeit – Allein, bezähmend Sinn und Selbst, nichts hoffend, ohne Besitz (Bhagavad-Gita, Vers 10)","reference":""},{"text":"„Auf seinem Fell spielten ein paar Sonnenflecken, während seine gelben Augen den Yogi fixierten.“","reference":"Helge Timmerberg: Die rote Olivetti. Mein ziemlich wildes Leben zwischen Bielefeld, Havanna und dem Himalaja. Piper, München/Berlin/Zürich 2016, ISBN 978-3-492-05755-4 , Zitat Seite 222."},{"text":"„Darum haben alle Yogis nach ihren Übungen immer dieses selige Grinsen im Gesicht.“","reference":"Kaya Yanar: Made in Germany. 3. Auflage. Wilhelm Heyne, München 2011, ISBN 978-3-453-60204-5, Seite 64."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Yogi","id":"88f5516be9d488"},"0079-006f:f3119db6c9771d":{"word":"Yogin","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Yo·gin","de-DE":"Yo·gin"},"forms":[{"form":"Jogi","tags":["variant"]},{"form":"Yogi","tags":["variant"]},{"form":"Jogin","tags":["alternative"]},{"form":"Yogin","tags":["Nominativ","Singular"]},{"form":"Yogini","tags":["feminine"]},{"form":"Yogins","tags":["Nominativ","Plural"]}],"senses":[{"definition":"indischer Asket, der Yoga praktiziert"}],"synonyms":[],"origins":["Entlehnung aus dem sanskritischen योगी (yogī) ^(→ sa) (Stamm: योगिन् (yogin) ^(→ sa))"],"examples":[{"text":"Ein Yogin kann sich, je nach Vorliebe, auf Shiva, Vishnu oder eine andere Gottheit ausrichten.","reference":"Anja Brandl: Yoga, der indische Erlösungsweg. 2004"},{"text":"Es ist nicht schwer zu verstehen, dass sie in dieser Form – als Yoginis, Gefährtinnen des Yogins – den tantrischen Asketen zu Göttinnen der Inspiration wurden.","reference":"Jürgen Schick: Bilder aus einer anderen Welt: die Götterwelt des tibetischen Buddhismus…. 2006"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Yogin","id":"f3119db6c9771d"},"0079-006f:490ce8ea69d008":{"word":"Yokohama","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Yo·ko·ha·ma","de-DE":"Yo·ko·ha·ma"},"forms":[{"form":"Jokohama","tags":["alternative"]},{"form":"Yokohamas","tags":["Genitiv","Singular"]},{"form":"des Yokohama","tags":["Genitiv","Singular"]},{"form":"des Yokohamas","tags":["Genitiv","Singular"]},{"form":"(das) Yokohama","tags":["Nominativ","Singular"]},{"form":"(dem) Yokohama","tags":["Dativ","Singular"]}],"senses":[{"definition":"Hafenstadt im Osten der japanischen Insel Honshu"}],"synonyms":[],"origins":[],"examples":[{"text":"„Er war bereits in Yokohama gewesen, einem anderen Brennpunkt der Kriminalität, und hatte sich an der Front bewährt.“","reference":"Jake Adelstein: Tokyo Vice. Eine gefährliche Reise durch die japanische Unterwelt. 1. Auflage. Riva, München 2022, ISBN 978-3-7423-2091-9, Seite 148 ."}],"idioms":[],"collocations":[],"derivations":["Yokohamahuhn"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Yokohama","id":"490ce8ea69d008"},"0079-006f:38ccd33ad50acd":{"word":"Yonkers","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Yon·kers","de-DE":"Yon·kers"},"forms":[{"form":"Yonkers’","tags":["Genitiv","Singular"]},{"form":"des Yonkers","tags":["Genitiv","Singular"]},{"form":"(das) Yonkers","tags":["Nominativ","Singular"]},{"form":"(dem) Yonkers","tags":["Dativ","Singular"]}],"senses":[{"definition":"Stadt im US-Bundesstaat New York"}],"synonyms":[],"origins":[],"examples":[{"text":"„Dann ging es nach Yonkers, mitten in Maranzanos Revier.“","reference":"David Chauvel: Cosa Nostra III. Die fetten Jahre. Schreiber & Leser, Hamburg 2009, ISBN 978-3-941-23907-4, Seite 127 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Yonkers","id":"38ccd33ad50acd"},"0079-006f:59e1fdfeb6e608":{"word":"York","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"York","de-DE":"York"},"forms":[{"form":"Yorks","tags":["Genitiv","Singular"]},{"form":"des York","tags":["Genitiv","Singular"]},{"form":"des Yorks","tags":["Genitiv","Singular"]},{"form":"(das) York","tags":["Nominativ","Singular"]},{"form":"(dem) York","tags":["Dativ","Singular"]}],"senses":[{"definition":"Stadt im Norden von England"}],"synonyms":[],"origins":[],"examples":[{"text":"„Laut Geoffrey von York erreichte er später im selben Jahr die Küsten Englands.“","reference":"Eliza Clark: Penance. Festa, Leipzig 2025, ISBN 978-3-986-76240-7, Seite 55 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"York","id":"59e1fdfeb6e608"},"0079-006f:a98f87ca3b22b0":{"word":"Yorkshire","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"York·shire","de-DE":"York·shire"},"forms":[{"form":"Yorkshires","tags":["Genitiv","Singular"]},{"form":"des Yorkshire","tags":["Genitiv","Singular"]},{"form":"des Yorkshires","tags":["Genitiv","Singular"]},{"form":"(das) Yorkshire","tags":["Nominativ","Singular"]},{"form":"(dem) Yorkshire","tags":["Dativ","Singular"]}],"senses":[{"definition":"Grafschaft in Nordengland"}],"synonyms":[],"origins":[],"examples":[{"text":"„Später stellte sich heraus, dass er kein Geringerer als Lord Northam war, von dessen uraltem Familiensitz, einer Burg an der Küste Yorkshires, man sich so viele seltsame Dinge erzählte.“","reference":"H.P. Lovecraft: Der Nachkomme. In: Das Gesamtwerk: Sämtliche Erzählungen und Zusammenarbeiten. Festa, Leipzig 2020, ISBN 978-3-865-52882-7, Seite 563/564 ."},{"text":"„Es handelte sich um eine Straßenkarte von Großbritannien, die Route bis zu Simons Häuschen in Yorkshire war grellorange eingezeichnet, außerdem gab es Anmerkungen, wie man sich auf den unbefestigten Straßen zu verhalten hatte.“","reference":"Don Winslow: London Undercover. Suhrkamp, Berlin 2015, ISBN 978-3-518-46580-6, Seite 228 ."},{"text":"„Ich las über den Mann ohne Gesicht, der den Trost seiner vor langer Zeit verstorbenen Mutter suchte und deshalb in einem kleinen Cottage in Great Ayton in Yorkshire erschien.“","reference":"Graham Masterton: Die Opferung. Festa, Leipzig 2014, ISBN 978-3-86552-343-3, Seite 161 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Yorkshire","id":"a98f87ca3b22b0"},"0079-006f:1b0676bd7eb611":{"word":"Yogalehrer","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Yo·ga·leh·rer","de-DE":"Yo·ga·leh·rer"},"forms":[{"form":"Jogalehrer","tags":["obsolete"]},{"form":"Yogalehrer","tags":["Nominativ","Singular"]},{"form":"Yogalehrern","tags":["Dativ","Plural"]},{"form":"Yogalehrers","tags":["Genitiv","Singular"]},{"form":"Yogalehrerin","tags":["feminine"]}],"senses":[{"definition":"Lehrer, der Yoga unterrichtet"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Yoga und Lehrer"],"examples":[{"text":"Der Yogalehrer kam heute zu spät, drei Übungen fielen deswegen aus.","reference":""},{"text":"„Weil es so gut gelaufen ist, habe ich damals ein Studio in Neusiedl am See aufgebaut und andere Yogalehrer als Partner hereingeholt.“","reference":"Wie die Corona-Krise die Yogalehrerin Claudia Vogt trifft. In: Der Standard digital. 27. März 2020 (URL, abgerufen am 2. Juli 2025) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Yogalehrer","id":"1b0676bd7eb611"},"0079-006f:f3e91f7a3a9c9d":{"word":"Yogalehrerin","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Yo·ga·leh·re·rin","de-DE":"Yo·ga·leh·re·rin"},"forms":[{"form":"Yogalehrer","tags":["masculine"]},{"form":"Jogalehrerin","tags":["obsolete"]},{"form":"Yogalehrerin","tags":["Nominativ","Singular"]},{"form":"Yogalehrerinnen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"weibliche Person, die Yoga unterrichtet"}],"synonyms":[],"origins":["Ableitung (Motion, Movierung) des Femininums aus der männlichen Form Yogalehrer mit dem Derivatem (Ableitungsmorphem) -in"],"examples":[{"text":"Meine ehemalige Yogalehrerin hat sich doch tatsächlich zur Kindergärtnerin umschulen lassen.","reference":""},{"text":"„Seit 2015 bin ich hauptberuflich selbstständige Yogalehrerin.“","reference":"Wie die Corona-Krise die Yogalehrerin Claudia Vogt trifft. In: Der Standard digital. 27. März 2020 (URL, abgerufen am 2. Juli 2025) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Yogalehrerin","id":"f3e91f7a3a9c9d"},"0079-006f:dc73f865999398":{"word":"YOLO","partOfSpeech":"Abkürzung","gender":"","hyphenation":{"de-CH":"YOLO","de-DE":"YOLO"},"forms":[{"form":"Yolo","tags":["variant"]}],"senses":[{"definition":"lebensbejahende Aufforderung, die Chance zu nutzen"}],"synonyms":[],"origins":["Abkürzung von englisch you only live once „du lebst nur einmal“"],"examples":[{"text":"„Ihre Eltern legten sich noch eine Fußmatte mit dem Aufdruck \"Carpe Diem\" vor die Tür, \"Nutze den Tag\". Ihre Kinder können damit nichts anfangen. \"Yolo\" ist ihr Motto: \"You only live once\". Meint in etwa das Gleiche - und ist das Jugendwort des Jahres.“","reference":"Jugendsprache: Yolo, Alter. spiegel online"},{"text":"„›Yolo‹ sei ein Akronym und stehe für ›You only live once‹ (Du lebst nur einmal) – eine Aufforderung, alle Chancen auf Erlebnisse zu nutzen.“","reference":"„Yolo“ ist das Jugendwort des Jahres 2012. Montag, 26.11.2012, 20:01 focus.de"},{"text":"„Viele Erwachsene werden mit dem Begriff wenig anfangen können: \"Yolo\" ist das Jugendwort des Jahres.“","reference":"Jugendwort des Jahres – \"Yolo\" vor \"wulffen\". welt.de"},{"text":"„Wenn Jugendliche miteinander sprechen, kommt es schon einmal vor, dass Erwachsene über den Inhalt rätseln müssen. \"Yolo\" ist eine der beliebtesten Kreationen.“","reference":"\"Yolo\" schlägt \"Wulffen\" und \"Komasutra\". 26. November 2012, 13:21 Uhr stern.de"},{"text":"Yolo hingegen wird fast ausschließlich als dankbare Ausrede für ungezügelten Genuss, Konsum oder Hedonismus verwendet. Das Smartphone für 500 Euro auf Pump kaufen? Yolo! Rauchen mit 15? Mathe Hausaufgaben vergessen? Yolo! Unter der Woche feiern gehen? Yolo! Sex ohne Kondom? Yolo!","reference":"Blog. Abgerufen am 11. März 2015."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"YOLO","id":"dc73f865999398"},"0079-006f:bfaf393109531c":{"word":"Yoni","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Yoni","de-DE":"Yoni"},"forms":[{"form":"Yoni","tags":["Nominativ","Singular"]}],"senses":[{"definition":"Symbol des weiblichen Geschlechts als göttliche schöpferische Kraft, das meist in Form eines runden Steines dargestellt wird"},{"definition":"weibliches Geschlechtsteil"}],"synonyms":["Dose","Fotze","Fut","Haartruhe","Loch","Muschi","Möse","Scheide","Spalte","Vagina","Venusspalte","Votze"],"origins":["Entlehnung aus dem sanskritischen योनि (yoni) ^(→ sa)"],"examples":[{"text":"„Die Verbindung von Lingam und Yoni, dem Zeichen des weiblichen Geschlechts, symbolisiert die Vereinigung des Götterpaares Shiva und Kali, die Synthese von männlicher Kraft und kreativer, weiblicher Energie, die mystische ‚Einheit in der Zweiheit‘.“","reference":"Erhard Hobert: Die zwei Gesichter Kalis. Chaos, Slums, Überbevölkerung – aber Kalkutta ist mehr als nur das deprimierende Schaufenster Indiens. In: Zeit Online. Nummer 47, 18. November 1988, ISSN 0044-2070 (URL, abgerufen am 15. April 2014) ."},{"text":"„Er legt seine warme Hand auf Ihre Yoni und die andere auf Ihren Herzbereich, um dann mit dieser Hand langsam in Richtung Yoni zu massieren.“","reference":"Annemarie Schweizer-Arau: Der sanfte Weg zum Wunschkind. IVF (fast) ohne Hormone. Kösel, 2015, ISBN 978-3-466-31054-8 (Zitiert nach Google Books)"},{"text":"„Mit den Fingerkuppen strich ich, die inneren Schamlippen durch die Spalte zwischen meinen Fingern gleiten lassend, ihre Yoni hinunter, […]“","reference":"Clemens Berger: Das Streichelinstitut. Roman. Wallstein, 2010, ISBN 978-3-8353-0619-6, Seite 129 (Zitiert nach Google Books)"},{"text":"„Sie trug keine Unterwäsche. Ihre Yoni leuchtete wie ein pinkfarbenes Bananenblatt.“","reference":"Monica Byrne: Die Brücke. Roman. Heyne, 2015 (übersetzt von Irene Holicki), ISBN 978-3-453-41784-7 (Zitiert nach Google Books)"},{"text":"„Und welche Frau guckt denn in ihre Yoni? Auch dafür braucht sie ’nen Spiegel. Doch sie weiß meist gar nicht, wie ihre Yoni aussieht.“","reference":"Claus Grütering: Meine Reise zum Tantra. Ein sinnliches Abenteuer im Amazonas. Janson, 2022, ISBN 978-3-939229-35-3 (Zitiert nach Google Books)"},{"text":"„Nun reckt sie ihm genüsslich ihren Po entgegen und er kann mit einer Hand ihre Po-Ritze und ihre Yoni streicheln.“","reference":"Juhi Charma: Das Kamasutra. Die Geheimnisse der altindischen Liebeskunst genießen. mvg, 2018, ISBN 978-3-86882-949-5, Seite 55 (Zitiert nach Google Books)"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Yoni","id":"bfaf393109531c"},"0079-006f:cf3a09cc647ff6":{"word":"Youngster","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Youngs·ter","de-DE":"Youngs·ter"},"forms":[{"form":"Youngster","tags":["Nominativ","Singular"]},{"form":"Youngstern","tags":["Dativ","Plural"]},{"form":"Youngsters","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Nachwuchssportler; neuer, junger Spieler in einer Mannschaft"},{"definition":"meist jüngere Person, die neu in eine bereits bestehenden Gruppe kommt und sich erst beweisen muss"},{"definition":"zweijähriges Pferd"},{"definition":"nicht erwachsene Person, die aber kein Kind mehr ist"}],"synonyms":["Anfänger","blutiger Anfänger","Debütant","der Neue / die Neue","Einsteiger","frisch von der Uni","frisches Blut","Frischling","Fuchs","Greenhorn","Grünschnabel","junger Dachs","junger Hüpfer","junger Spritzer","junger Spund","Jungfuchs","Jungspund","Kadett","Küken","Milchbart","neu hier","neu im Geschäft","Neueinsteiger","Neuling","Newbie","Newcomer","noch nicht lange dabei","Noob","Novize","Nullanfänger (Sprachkurs)","Rookie","Rotarsch","Springinsfeld","Spund","unbeschriebenes Blatt"],"origins":["Entlehnung aus dem englischen youngster ^(→ en)"],"examples":[{"text":"Der Youngster gab bei seinem ersten Spiel mit zweit Toren einen famosen Einstand.","reference":""},{"text":"„Als Youngster in der Freiheitsbewegung hatte Torvalds ausgerechnet jenen Teil eines Betriebssystems programmiert, der Stallman und seiner Gruppe noch fehlte.“","reference":"Gunhild Lütge: Programmierer aller Länder vereinigt Euch!. In: Zeit Online. Nummer 44, 23. Oktober 2003, ISSN 0044-2070 (URL, abgerufen am 26. März 2015) ."},{"text":"„Die fünf Youngster spielen die auf wiederkehrenden Mustern beruhenden Reels und Jigs: schnelle Tänze, wie man sie vor ein paar Hundert Jahren noch überall in Westeuropa hörte.“","reference":"Frank Patalong: Die Hüter des Schatzes. In: SPIEGEL GESCHICHTE. Nummer 5: Die Kelten, 2017 , Seite 126-132, Zitat Seite 132."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Youngster","id":"cf3a09cc647ff6"},"0079-006f:638747c5b6efe1":{"word":"Yomud","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Yo·mud","de-DE":"Yo·mud"},"forms":[{"form":"Yomud","tags":["Nominativ","Singular"]},{"form":"Yomuds","tags":["Nominativ","Plural"]}],"senses":[{"definition":"zentralasiatischer Teppich"}],"synonyms":[],"origins":[],"examples":[{"text":"In meinem Wohnzimmer liegt ein Yomud und in meinem Arbeitszimmer ein Türük.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Yomud","id":"638747c5b6efe1"},"0079-006f:f92b17fd4befd4":{"word":"Yohimbin","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Yo·him·bin","de-DE":"Yo·him·bin"},"forms":[{"form":"Yohimbin","tags":["Nominativ","Singular"]},{"form":"Yohimbins","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Indolalkaloid aus der Rinde des Yohimbe-Baums"}],"synonyms":[],"origins":[],"examples":[{"text":"Yohimbin wird therapeutisch gegen Erektionsstörungen eingesetzt.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Yohimbin","id":"f92b17fd4befd4"},"0079-006f:e52e38996a2b4b":{"word":"YouTuber","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"You·Tuber","de-DE":"You·Tuber"},"forms":[{"form":"Youtuber","tags":["variant"]},{"form":"YouTubern","tags":["Dativ","Plural"]},{"form":"YouTubers","tags":["Genitiv","Singular"]},{"form":"YouTuberin","tags":["feminine"]}],"senses":[{"definition":"Person, die auf der Internetseite »YouTube« Videos veröffentlicht"}],"synonyms":[],"origins":[],"examples":[{"text":"In dieser Fotostrecke stellen wir sieben bekannte deutsche YouTuber vor und zeigen, welche ihre beliebtesten Videos sind.","reference":"Bekannte Youtuber. Abgerufen am 21. Januar 2016."},{"text":"Ist es also ein erfolgversprechendes Berufsziel, YouTuber zu werden?","reference":"Fehlender Parameter (Hilfe) Abgerufen am 21. Januar 2016."},{"text":"„Sie beschäftigt aktuell über 70 Mitarbeiter, drei von ihnen umgarnen YouTuber und Blogger.“","reference":"Nina Piatscheck: Rote Lippen, schwarze Zahlen – Teenies im Spachtelwahn. In: DIE ZEIT. Nummer 20, 11. Mai 2017, ISSN 0044-2070, Seite 27 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"YouTuber","id":"e52e38996a2b4b"},"0079-006f:e4cf41c5c07441":{"word":"Yogini","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Yogi·ni","de-DE":"Yogi·ni"},"forms":[{"form":"Yogi","tags":["masculine"]},{"form":"Yogini","tags":["Nominativ","Singular"]},{"form":"Yoginis","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Yoga praktizierende Frau"}],"synonyms":[],"origins":[],"examples":[{"text":"„Die Hauptstadt der Yogis und Yoginis sowie der weltbekanntesten und teuersten Yoga-Lehrer liegt nicht am Ganges, sondern an der Limmat“","reference":"Daniele Muscionico: Die Sonne geht im Steißbein unter. In: Zeit Online. Nummer 49, 2011, ISSN 0044-2070 (URL, abgerufen am 22. Januar 2016) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Yogini","id":"e4cf41c5c07441"},"0079-006f:9e6b53b4911c75":{"word":"YouTube-Kanal","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"You·Tube-Ka·nal","de-DE":"You·Tube-Ka·nal"},"forms":[{"form":"Youtube-Kanal","tags":["alternative"]},{"form":"YouTube-Kanals","tags":["Genitiv","Singular"]},{"form":"YouTube-Kanäle","tags":["Nominativ","Plural"]},{"form":"YouTube-Kanälen","tags":["Dativ","Plural"]}],"senses":[{"definition":"individuell anpassbare Seite eines angemeldeten Benutzers innerhalb der Internetplattform YouTube, auf der dieser zum Beispiel Videos hochladen und veröffentlichen kann"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven YouTube und Kanal"],"examples":[{"text":"„Der YouTube-Kanal ist das Profil einer Person oder eines Unternehmens auf YouTube.“","reference":"Marius Szoltysek, Christian Tembrink, Hendrik Unger: Das Buch zum erfolgreichen Online-Marketing mit YouTube. O’Reilly Verlag, Köln 2014, ISBN 978-3-95561-520-8, Seite 29, DNB 1037409167 (zitiert nach Google Books, abgerufen am 6. November 2017) ."},{"text":"„Er hat ganz einfach seinen eigenen YouTube-Kanal gegründet und will dort in genüsslichen Fünf-Minuten-Videos über alles Mögliche reden: über Stücke, die ihm am Herzen liegen, über Politisches, Soziales und Absurdes.“","reference":"Christine Lemke-Matwey: Wie geht noch mal das „Magnificat“?. In: Zeit Online. Nummer 35/2016, 18. August 2016, ISSN 0044-2070 (URL, abgerufen am 6. November 2017) ."},{"text":"„Für das Personalmarketing ist ein YouTube-Kanal besonders interessant, da man die Videos, anders als bei Xing oder Facebook, auch ohne eine Anmeldung anschauen kann.“","reference":"Caroline Bürge: Personalmarketing im Internet. Eine rechtliche und betriebswirtschaftliche Betrachtung. Springer Gabler, Wiesbaden 2016, ISBN 978-3-658-11880-8, Seite 56, DNB 1079448578 (zitiert nach Google Books, abgerufen am 6. November 2017) ."},{"text":"„‚Die Bundesregierung will auf ihrem YouTube-Kanal in Bild und Wort über ihre Arbeit informieren.‘“","reference":"Film ab, jetzt kommt der Krieg!. In: Spiegel Online. 18. November 2011, ISSN 0038-7452 (URL, abgerufen am 6. November 2017) ."},{"text":"„Jugendkultureller Raum umfasst digitale und territoriale Orte, zum Beispiel persönliche YouTube-Kanäle, Performance- und Drehorte.“","reference":"Christoph Eisemann: C Walk auf YouTube. Sozialraumkonstruktion, Aneignung und Entwicklung in einer digitalen Jugendkultur. Springer VS, Wiesbaden 2015, ISBN 978-3-658-06429-7, Seite 306, DNB 1061026965 (zitiert nach Google Books, abgerufen am 6. November 2017) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"YouTube-Kanal","id":"9e6b53b4911c75"},"0079-006f:a400e6984f6743":{"word":"Yogakurs","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Yo·ga·kurs","de-DE":"Yo·ga·kurs"},"forms":[{"form":"Jogakurs","tags":["obsolete"]},{"form":"Yogakurs","tags":["Nominativ","Singular"]},{"form":"Yogakurse","tags":["Nominativ","Plural"]},{"form":"Yogakursen","tags":["Dativ","Plural"]},{"form":"Yogakurses","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Veranstaltungsreihe zum Erlernen und/oder Ausüben von Yoga"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Yoga und Kurs"],"examples":[{"text":"„Wenn man die Teilnehmer nach einem Yogakurs beobachtet, haben sie immer einen leicht bekifften Gesichtsausdruck.“","reference":"Kaya Yanar: Made in Germany. 3. Auflage. Wilhelm Heyne, München 2011, ISBN 978-3-453-60204-5, Seite 64."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Yogakurs","id":"a400e6984f6743"},"0079-006f:146ebc16566b16":{"word":"Yogaschule","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Yo·ga·schu·le","de-DE":"Yo·ga·schu·le"},"forms":[{"form":"Jogaschule","tags":["obsolete"]},{"form":"Yogaschule","tags":["Nominativ","Singular"]},{"form":"Yogaschulen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Einrichtung, in der Yoga unterrichtet wird"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Yoga und Schule"],"examples":[{"text":"„Um keine weiteren Missverständnisse aufkommen zu lassen, kündigte Francesco seine Mitgliedschaft im Fitnessstudio und meldete sich in einer Yogaschule an.“","reference":"Kaya Yanar: Made in Germany. 3. Auflage. Wilhelm Heyne, München 2011, ISBN 978-3-453-60204-5, Seite 64."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Yogaschule","id":"146ebc16566b16"},"0079-006f:ce50377699845c":{"word":"Yogasitz","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Yo·ga·sitz","de-DE":"Yo·ga·sitz"},"forms":[{"form":"Yogasitz","tags":["Nominativ","Singular"]},{"form":"Yogasitzes","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Art und Weise des Sitzens, die im Yoga ausgeübt wird"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Yoga und Sitz"],"examples":[{"text":"„Fassungslos blicke ich zu Guri, der mit geschlossenen Augen, in sich versunken und völlig entspannt im Yogasitz am Boden kauert.“","reference":"Piet Bogner: Die Ahnen rufen. Walter-Verlag, 1982, ISBN 9783530092028, Seite 123"},{"text":"„Die Aufgabe bestand darin, sich im Yogasitz auf den Boden zu hocken, Arm-, Schulter-, Rücken- und Bauchmuskulatur zu entspannen und dabei an etwas möglichst Trauriges zu denken, […]“","reference":"Klagenfurter Texte zum Ingeborg-Bachmann-Preis 1983. List Verlag, München 1983, Seite 170"},{"text":"„Sie sitzen in der Kammer der Heidana, direkt neben dem Trainingsraum, die Tür ist abgeschlossen: nur sie beide, Gulla und die Trainerin, die Beine im Yogasitz, die Bäuche vorgewölbt, die Arme locker herabfallend.“","reference":"Lesebuch der deutschen Science Fiction 1984. Corian, 1983, ISBN 389048204X, Seite 36"},{"text":"„Und da ist die uralte amerikanische Lady, die so gar nicht dem Klischee entspricht, sondern gebildet, charmant und fast noch verführerisch schön ist und im Yogasitz auf dem Bett hockt: […]“","reference":"Rudolf Braunburg: Transsibirische Eisenbahn. Ellert & Richter, 1987, Seite 9"},{"text":"„Er hockt im Yogasitz an Deck des Schiffes, das eine illustre Gemeinde gleich von Ko Samui nach Ko Phangan bringen wird: Junge Europäer, Amerikaner, Südafrikaner und Australier, dreihundert, vielleicht sind es auch fünfhundert.“","reference":"Lasse Dudde: Magic Mushrooms in Suppen. In: Spiegel Online. 11. Dezember 2000, ISSN 0038-7452 (URL, abgerufen am 6. Januar 2019) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Yogasitz","id":"ce50377699845c"},"0079-006f:c79e4d1e8ed69b":{"word":"youtuben","partOfSpeech":"Verb","gender":"","hyphenation":{"de-CH":"you·tuben","de-DE":"you·tuben"},"forms":[{"form":"haben","tags":["Hilfsverb","Perfekt"]},{"form":"youtub!","tags":["Imperativ","Singular"]},{"form":"youtube","tags":["Präsens"]},{"form":"youtubt","tags":["Präsens"]},{"form":"youtube!","tags":["Imperativ","Singular"]},{"form":"youtuben","tags":["Aktiv","Infinitiv","Präsens"]},{"form":"youtubst","tags":["Präsens"]},{"form":"youtubt!","tags":["Imperativ","Plural"]},{"form":"youtubte","tags":["Präteritum"]},{"form":"geyoutubt","tags":["Partizip II","Perfekt"]},{"form":"youtubend","tags":["Partizip","Präsens","Aktiv"]},{"form":"du youtubst","tags":["2. Person","Singular","Präsens","Aktiv","Indikativ"]},{"form":"ich youtube","tags":["1. Person","Singular","Präsens","Aktiv","Indikativ"]},{"form":"ihr youtubt","tags":["2. Person","Plural","Präsens","Aktiv","Indikativ"]},{"form":"zu youtuben","tags":["Aktiv","erweitert","Infinitiv"]},{"form":"du youtubest","tags":["2. Person","Singular","Präsens","Aktiv","Konjunktiv I"]},{"form":"ich youtubte","tags":["1. Person","Singular","Präteritum","Aktiv","Indikativ"]},{"form":"ihr youtubet","tags":["2. Person","Plural","Präsens","Aktiv","Konjunktiv I"]},{"form":"sie youtuben","tags":["3. Person","Plural","Präsens","Aktiv","Indikativ"]},{"form":"wir youtuben","tags":["1. Person","Plural","Präsens","Aktiv","Indikativ"]},{"form":"du youtubtest","tags":["2. Person","Singular","Präteritum","Aktiv","Indikativ"]},{"form":"ihr youtubtet","tags":["2. Person","Plural","Präteritum","Aktiv","Indikativ"]},{"form":"sie youtubten","tags":["3. Person","Plural","Präteritum","Aktiv","Indikativ"]},{"form":"wir youtubten","tags":["1. Person","Plural","Präteritum","Aktiv","Indikativ"]},{"form":"youtuben Sie!","tags":["Imperativ","Höflichkeitsform","Präsens","Aktiv"]},{"form":"geyoutubt haben","tags":["Aktiv","Infinitiv","Perfekt"]},{"form":"habe geyoutubt!","tags":["Imperativ","uncommon","2. Person","Singular","Perfekt","Aktiv"]},{"form":"habt geyoutubt!","tags":["Imperativ","uncommon","2. Person","Plural","Perfekt","Aktiv"]},{"form":"du hast geyoutubt","tags":["2. Person","Singular","Perfekt","Aktiv","Indikativ"]},{"form":"du wirst youtuben","tags":["2. Person","Singular","Futur I","Aktiv","Indikativ"]},{"form":"er/sie/es youtube","tags":["3. Person","Singular","Präsens","Aktiv","Konjunktiv I"]},{"form":"er/sie/es youtubt","tags":["3. Person","Singular","Präsens","Aktiv","Indikativ"]},{"form":"es wird geyoutubt","tags":["3. Person","Singular","Präsens","Vorgangspassiv","Indikativ"]},{"form":"er/sie/es youtubte","tags":["3. Person","Singular","Präteritum","Aktiv","Indikativ"]},{"form":"es werde geyoutubt","tags":["3. Person","Singular","Präsens","Vorgangspassiv","Konjunktiv I"]},{"form":"es wurde geyoutubt","tags":["3. Person","Singular","Präteritum","Vorgangspassiv","Indikativ"]},{"form":"es würde geyoutubt","tags":["3. Person","Singular","Präteritum","Vorgangspassiv","Konjunktiv II"]},{"form":"geyoutubt zu haben","tags":["Aktiv","erweitert","Infinitiv"]},{"form":"ich habe geyoutubt","tags":["1. Person","Singular","Perfekt","Aktiv","Indikativ"]},{"form":"ich werde youtuben","tags":["1. Person","Singular","Futur I","Aktiv","Indikativ"]}],"senses":[{"definition":"ein Video (für das Videoportal YouTube®) erstellen"},{"definition":"das Videoportal YouTube® nutzen, etwa dort Videos ansehen oder Videos suchen"}],"synonyms":[],"origins":["Der gegen Ende des ersten Jahrzehnts des 21. Jahrhunderts aufgekommene Neologismus kann entweder als Bildung zum Namen der Plattform YouTube oder als Lehnwort zum englischen Verb to youtube ^(→ en)/to YouTube ^(→ en) eingeordnet werden."],"examples":[{"text":"„Youtuber aber tun andere Dinge, sie youtuben, auch wenn niemand dieses Verb benutzt […].“","reference":"Quentin Lichtblau: Youtube sprechen lernen. In: sueddeutsche.de. 23. Mai 2019, ISSN 0174-4917 (URL, abgerufen am 31. Januar 2020) ."},{"text":"„Auf ‚LeNews‘ präsentiert und kommentiert er zweimal wöchentlich Nachrichten - von reißerischen Schlagzeilen bis skurrilen News - alles aufbereitet im Jugendslang. Außerdem youtubt er zu Games und Kurzfilmen.“","reference":"Fashion, Fun und Fame: Deutsche YouTube-Stars. In: Welt Online. 27. Januar 2015, ISSN 0173-8437 (URL, abgerufen am 31. Januar 2020) ."},{"text":"„Ok, wir sind in 2018, ich gebe zu, ich habe gar nichts herausgekramt, sondern das Smartphone in die Hand genommen und gegoogelt, geyoutubt und gelacht und geweint.“","reference":"Oliver Rasche: Warum wir uns alle die 100. „Bravo Hits“-CD kaufen sollten. In: Welt Online. 23. Februar 2018, ISSN 0173-8437 (URL, abgerufen am 31. Januar 2020) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"youtuben","id":"c79e4d1e8ed69b"},"0079-006f:7aba449e9004f0":{"word":"YouTuberin","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"You·Tube·rin","de-DE":"You·Tube·rin"},"forms":[{"form":"YouTuber","tags":["masculine"]},{"form":"Youtuberin","tags":["alternative"]},{"form":"YouTuberinnen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"weibliche Person, die auf der Internetseite »YouTube« Videos veröffentlicht"}],"synonyms":[],"origins":["Ableitung (Motion, Movierung) des Femininums aus der männlichen Form YouTuber mit dem Derivatem (Ableitungsmorphem) -in"],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"YouTuberin","id":"7aba449e9004f0"},"0079-006f:5d2066aaa95a62":{"word":"Yogalates","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Yo·ga·la·tes","de-DE":"Yo·ga·la·tes"},"forms":[{"form":"Yogalates","tags":["Nominativ","Singular"]}],"senses":[{"definition":"Training, bei dem Elemente von Yoga und Pilates kombiniert werden"}],"synonyms":[],"origins":["Kofferwort aus Yoga und Pilates"],"examples":[{"text":"„Sportive Naturen betätigen sich in einem der zahlreichen Amalgame aus der alten indischen Meditationstechnik und (Fun)Sport, etwa: SurfYoga, YogaWalking oder Yogalates (ein Kofferwort aus Yoga und Pilates).“","reference":"Fehlender Parameter (Hilfe) Tobias Kurfer: Abgerufen am 11. Februar 2022."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Yogalates","id":"5d2066aaa95a62"},"0079-006f:bb7a1afdd96188":{"word":"Yongin","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Yon·gin","de-DE":"Yon·gin"},"forms":[{"form":"Yongins","tags":["Genitiv","Singular"]},{"form":"des Yongin","tags":["Genitiv","Singular"]},{"form":"des Yongins","tags":["Genitiv","Singular"]},{"form":"(das) Yongin","tags":["Nominativ","Singular"]},{"form":"(dem) Yongin","tags":["Dativ","Singular"]}],"senses":[{"definition":"Stadt im Nordwesten von Südkorea"}],"synonyms":[],"origins":[],"examples":[{"text":"„Doch der Elefantenbulle, der in Everland Zoo im südkoreanischen Yongin lebt, ahmt offensichtlich einige koreanische Vokabeln nach.“","reference":"Nina Weber: Koshik, der sprechende Elefant. In: Spiegel Online. 1. November 2012, ISSN 0038-7452 (URL, abgerufen am 1. Januar 2024) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Yongin","id":"bb7a1afdd96188"},"0079-006f:35842ecde15cad":{"word":"Yorubaland","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Yo·ru·ba·land","de-DE":"Yo·ru·ba·land"},"forms":[{"form":"Yorubaland","tags":["Nominativ","Singular"]},{"form":"Yorubalands","tags":["Genitiv","Singular"]},{"form":"Yorubalandes","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Region im Südwesten von Nigeria, welche das Hauptsiedlungsgebiet des Volkes der Yoruba darstellt"}],"synonyms":[],"origins":[],"examples":[{"text":"„Von Usen, nordwestlich von Benin-City, verliefen Handelsrouten ins Yorubaland, über Owo nach Nupe und über Akure nach Ottun, an der Grenze zu Oyo.“","reference":"Leonhard Harding: Das Königreich Benin. Geschichte – Kultur – Wirtschaft. Oldenbourg, München 2010, ISBN 978-3-486-59757-8, Seite 42 ."},{"text":"„›Aus welchem Teil von Yorubaland stammen Sie?‹, fragt mich der Chief.“","reference":"Femi Kayode: Lightseekers. btb, München 2022, ISBN 978-3-442-77011-3, Seite 179 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Yorubaland","id":"35842ecde15cad"},"0079-006f:2ba951fa505ee2":{"word":"Yogamatte","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Yo·ga·mat·te","de-DE":"Yo·ga·mat·te"},"forms":[{"form":"Yogamatte","tags":["Nominativ","Singular"]},{"form":"Yogamatten","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Matte, auf der Yoga ausgeübt wird"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Yoga und Matte"],"examples":[{"text":"„Das zusammengerollte Ding unter Graubarts Arm: eine Yogamatte.“","reference":"Chuck Palahniuk: Adjustment Day. Festa, Leipzig 2018, ISBN 978-3865526878, Seite 11 ."},{"text":"„Es gibt Gewichte, Yogamatten, sogar eine kleine Stereoanlage, um beim Trainieren Musik abzuspielen.“","reference":"Carlton Mellick III: Exercise Bike. Festa, Leipzig 2024, Seite 89 ."},{"text":"„Ihre Arbeitskabine in einer Ecke des Büroraums konnte man nicht wirklich als Büro bezeichnen, doch war sie immer noch besser als die der meisten anderen Post-Reporter. Drei mal drei Meter, vollgestopft mit Büchern, Zeitschriften, Zeitungen, Aktenordnern, Reisetaschen und Rucksäcken mit Rollen, Yogamatten und weiteren Fitness-Utensilien.“","reference":"Mark Greaney: The Gray Man - Operation Back Blast. Festa, Leipzig 2021, ISBN 978-3-86552-966-4, Seite 136 ."},{"text":"„Ich backte Pfannkuchen für sie, kaufte ihr eine Yogamatte, schlief an den richtigen Tagen mit ihr.“","reference":"Mohammed Hanif: Rote Vögel. Hoffmann und Campe, Hamburg 2019, ISBN 978-3-455-00516-5, Seite 181 ."},{"text":"„Am anderen Ende des Raums verknotete sich seine Frau Mary auf einer lila Yogamatte, was zu ihrer festen Morgenroutine gehörte.“","reference":"Ben Coes: Ein Tag zum Töten. Festa, Leipzig 2018, ISBN 978-3-86552-624-3, Seite 51 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Yogamatte","id":"2ba951fa505ee2"},"0079-006f:f1d08d9e030bd7":{"word":"Yobe","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Yobe","de-DE":"Yobe"},"forms":[{"form":"Yobes","tags":["Genitiv","Singular"]},{"form":"des Yobe","tags":["Genitiv","Singular"]},{"form":"des Yobes","tags":["Genitiv","Singular"]},{"form":"(das) Yobe","tags":["Nominativ","Singular"]},{"form":"(dem) Yobe","tags":["Dativ","Singular"]}],"senses":[{"definition":"nigerianischer Bundesstaat"}],"synonyms":[],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Yobe","id":"f1d08d9e030bd7"},"0079-006f:190c8999f35f5e":{"word":"Yola","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Yola","de-DE":"Yola"},"forms":[{"form":"Yolas","tags":["Genitiv","Singular"]},{"form":"des Yola","tags":["Genitiv","Singular"]},{"form":"des Yolas","tags":["Genitiv","Singular"]},{"form":"(das) Yola","tags":["Nominativ","Singular"]},{"form":"(dem) Yola","tags":["Dativ","Singular"]}],"senses":[{"definition":"Hauptstadt des nigerianischen Bundesstaats Adamawa"}],"synonyms":[],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Yola","id":"190c8999f35f5e"},"0079-006f:616de63d7b84fa":{"word":"Yogaklasse","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Yo·ga·klas·se","de-DE":"Yo·ga·klas·se"},"forms":[{"form":"Yogaklasse","tags":["Nominativ","Singular"]},{"form":"Yogaklassen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"von einem Lehrer/Instruktor geführter Unterricht im Yoga oder einzelne Unterrichtseinheit"}],"synonyms":[],"origins":["Determinativkompositum (Zusammensetzung) aus den Substantiven Yoga und Klasse"],"examples":[{"text":"„Diese Yogaklasse ist speziell für Menschen konzipiert, die viel sitzen und Verspannungen im Körper verspüren.“","reference":"Stundenplan - Yogahaus Dresden - Schau jetzt vorbei, Yogahaus Dresden, 2023-05-11. Aus dem WebXL-Korpus des Digitalen Wörterbuchs der deutschen Sprache, abgerufen am 18. Januar 2025."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Yogaklasse","id":"616de63d7b84fa"},"0079-006f:3cb1b76dc0b632":{"word":"Yongsan","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Yong·san","de-DE":"Yong·san"},"forms":[{"form":"Yongsans","tags":["Genitiv","Singular"]},{"form":"des Yongsan","tags":["Genitiv","Singular"]},{"form":"des Yongsans","tags":["Genitiv","Singular"]},{"form":"(das) Yongsan","tags":["Nominativ","Singular"]},{"form":"(dem) Yongsan","tags":["Dativ","Singular"]}],"senses":[{"definition":"Stadtbezirk von Seoul"}],"synonyms":[],"origins":[],"examples":[{"text":"„Im Frühjahr 1985 ließ er im Einwohnermeldeamt von Yongsan die annullierten Personalakten wiederherstellen, gab seine Fingerabdrücke ab und bekam bald darauf einen Personalausweis auf den Namen Kim Giyoung ausgehändigt.“","reference":"Kim Young-ha: Im Reich der Lichter. Heyne, München 2008, ISBN 978-3-453-40544-8, Seite 84 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Yongsan","id":"3cb1b76dc0b632"},"0079-006f:ae4f59612df6ad":{"word":"Youngstown","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Youngs·town","de-DE":"Youngs·town"},"forms":[{"form":"Youngstowns","tags":["Genitiv","Singular"]},{"form":"des Youngstown","tags":["Genitiv","Singular"]},{"form":"des Youngstowns","tags":["Genitiv","Singular"]},{"form":"(das) Youngstown","tags":["Nominativ","Singular"]},{"form":"(dem) Youngstown","tags":["Dativ","Singular"]}],"senses":[{"definition":"Ort im US-Bundesstaat New York"}],"synonyms":[],"origins":[],"examples":[{"text":"„›Ich liebäugele mit einer dieser großen Villen auf den Klippen bei Youngstown. Ganz in der Nähe von Fort Niagara.‹“","reference":"Dan Simmons: Eiskalt erwischt. Festa, Leipzig 2012, ISBN 978-3-86552-186-6, Seite 109 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Youngstown","id":"ae4f59612df6ad"},"0079-006f:b47ec0b0d4ebd3":{"word":"Yorkshire Pudding","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"York·shire Pud·ding","de-DE":"York·shire Pud·ding"},"forms":[{"form":"Yorkshire Pudding","tags":["Nominativ","Singular"]},{"form":"Yorkshire Puddings","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Backwerk aus der englischen Küche, das meistens als Beilage zu Fleischgerichten gegessen wird"}],"synonyms":[],"origins":[],"examples":[{"text":"„Der Sonntag sollte doch eigentlich der Entspannung dienen - Rinderbraten mit Yorkshire Pudding, die Füße vor dem Fernseher hoch gelegt, dass einem die Zeitung vom Schoß rutscht.“","reference":"Ian Rankin: Wolfsmale. Goldmann, München 2001, ISBN 978-3-442-44609-0, Seite 8 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Yorkshire Pudding","id":"b47ec0b0d4ebd3"},"0079-006f:ce4d78926fd9b2":{"word":"Yogahose","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Yo·ga·ho·se","de-DE":"Yo·ga·ho·se"},"forms":[{"form":"Yogahose","tags":["Nominativ","Singular"]},{"form":"Yogahosen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Hose, die beim Yoga getragen wird, für Bequemlichkeit bei Yoga-Übungen entworfen wurde"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Yoga und Hose"],"examples":[{"text":"„Die Frau trug eine schwarze Yogahose und ein grellpinkes Tanktop, das ihre straffen gebräunten Arme zur Geltung brachte.“","reference":"Don Bentley: The Outside Man. Festa, Leipzig 2025, ISBN 978-3-98676-247-6, Seite 8 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Yogahose","id":"ce4d78926fd9b2"},"0079-006f:f7f4b560484180":{"word":"Yonghe","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Yonghe","de-DE":"Yonghe"},"forms":[{"form":"Yonghes","tags":["Genitiv","Singular"]},{"form":"des Yonghe","tags":["Genitiv","Singular"]},{"form":"des Yonghes","tags":["Genitiv","Singular"]},{"form":"(das) Yonghe","tags":["Nominativ","Singular"]},{"form":"(dem) Yonghe","tags":["Dativ","Singular"]}],"senses":[{"definition":"Stadtteil von Neu-Taipeh"}],"synonyms":[],"origins":[],"examples":[{"text":"„Ein alter Militärdienstkumpel von Fat behauptete, dessen Freundin zu kennen, die im Bezirk Yonghe einen zweitklassigen Karaokeschuppen betreibe.“","reference":"Chang Kuo-Li: Der grillende Killer. Droemer, München 2022, ISBN 978-3-426-28389-9, Seite 142 ."},{"text":"„Sie wohnte im Liuhe-Markt von Yonghe, einem Gewirr von kleinen Gassen und Gässchen, die irgendwann alle in einen Tunnel mündeten, eine überdachte Fußgängerpassage, in der Straßenhändler Essen und allen möglichen Krimskrams feilboten.“","reference":"Katniss Hsiao: Das Parfüm des Todes. Suhrkamp, Berlin 2024, ISBN 978-3-518-47443-3, Seite 21 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Yonghe","id":"f7f4b560484180"},"0079-006f:a360e6322f4ee9":{"word":"Yogastudio","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Yo·ga·stu·dio","de-DE":"Yo·ga·stu·dio"},"forms":[{"form":"Yogastudio","tags":["Nominativ","Singular"]},{"form":"Yogastudios","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Raum, in dem Yoga geübt wird"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Yoga und Studio"],"examples":[{"text":"„Es war eine Stadt voller Hochschuldozenten, Golden Retriever und jungen Frauen mit weißen Sneakers auf dem Weg zum Yogastudio.“","reference":"Patricia Evangelista: Some People Need Killing. Eine Geschichte der Morde in meinem Land. CulturBooks, Hamburg 2025, ISBN 978-3-95988-247-7, Seite 152 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Yogastudio","id":"a360e6322f4ee9"}};
